                    + '" stroke="' + colour + '"/>'
                    + '<g data-open="' + esc(item.id) + '" data-kind="' + esc(side) + '">'
                    + '<title>' + esc(tip) + '</title>'
                    + '<circle cx="' + x + '" cy="' + y + '" r="3.4" fill="' + colour + '"/>'
